(() => {
  const base = window.WELLNESS_FOODS || [];
  const key = (food) => String(food.name || "").normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").toLowerCase().trim();
  const seen = new Set(base.map(key));
  window.WELLNESS_FOODS = [...base, ...window.CIQUAL_FOODS.filter((food) => !seen.has(key(food)))];
})();
